const environment = relayEnvironmentWithMissingFieldHandlerForNode()

export interface CopilotChatInputPartialProps extends CopilotChatPayload {
  searchWorkerFilePath: string
  ssoOrganizations?: CopilotChatOrg[]
  showHeader?: boolean
  userIsOnboarding?: boolean
  displayName?: string
  dashboardModulesEnabled?: boolean
  hasCEorCBAccess?: boolean
  loopsClientUrl?: string
  graphqlApiUrl?: string
  /** for testing only */
  testReducerState?: CopilotChatState
}

export function CopilotChatInputPartial(props: CopilotChatInputPartialProps) {
  const [failedTasks, setFailedTasks] = useState<CreateTaskMutationParams[]>([])

  const {createTask} = useCreateTask({
    onError: (_, variables) => {
      setFailedTasks(prev => [{...variables}, ...prev])
    },
  })
  const navigate = useNavigate()
  const {agentsEnabled, dashboardModulesEnabled} = props
  const isAgentTaskListEnabled = isFeatureEnabled('copilot_agent_task_list_v2')

  const handleUserSubmit = useCallback(
    async (
      content: string,
      selectedRepo: AgentDropdownRepository | null,
      selectedBranch: string,
      selectedAgent: SelectedAgent,
    ) => {
      setFailedTasks([])
      const trimmedContent = content.trim()
      if (trimmedContent === '' || !selectedBranch || selectedBranch.trim() === '') return
      if (selectedRepo) {
        const shouldCreateTaskFromList =
          dashboardModulesEnabled !== undefined ? dashboardModulesEnabled : isAgentTaskListEnabled && agentsEnabled
        if (isFeatureEnabled('copilot_default_to_task_input') && !shouldCreateTaskFromList) {
          // Navigate to the agents view if the NewTaskChatInput is being used and the agents list is not present.
          const params = JSON.stringify({
            text: content,
            selectedRepo,
            selectedBranch,
            selectedAgent,
          })
          copilotLocalStorage.setTaskEntrypointMessage(params)
          navigate(COPILOT_AGENTS_PATH, {preventTurbo: true})
          return
        }

        // This mutation will automatically invalidate and refetch the tasks after completion
        createTask({
          nwo: selectedRepo.nameWithOwner,
          problemStatement: trimmedContent,
          baseRef: selectedBranch,
          eventType: 'dashboard',
          selectedAgent,
        })
      }
    },
    [createTask, navigate, agentsEnabled, dashboardModulesEnabled, isAgentTaskListEnabled],
  )

  const handleUserSubmitRef = useRef(handleUserSubmit)

  useEffect(() => {
    handleUserSubmitRef.current = handleUserSubmit
  }, [handleUserSubmit])

  const plugins = useImmersivePlugins({
    payload: {
      sparkEnabled: props.sparkEnabled,
      agentsEnabled: props.agentsEnabled,
      dashboardModulesEnabled: props.dashboardModulesEnabled,
      loopsClientUrl: props.loopsClientUrl,
      graphqlApiUrl: props.graphqlApiUrl,
    },
    handleUserSubmitRef,
  })

  return (
    <RelayEnvironmentProvider environment={environment}>
      <ImmersivePluginsProvider plugins={plugins}>
        <CopilotChatProvider
          copilotChatPayload={props}
          mode="immersive"
          refs={[]}
          ssoOrganizations={props.ssoOrganizations ?? []}
          testReducerState={props.testReducerState}
          threadId={null}
          workerPath={props.searchWorkerFilePath}
        >
          <StandaloneInput
            showHeader={props.showHeader}
            userIsOnboarding={props.userIsOnboarding}
            displayName={props.displayName}
            shouldClearTextOnSubmit={props.dashboardModulesEnabled}
            hasCEorCBAccess={props.hasCEorCBAccess}
            handleUserSubmit={handleUserSubmit}
            agentsEnabled={props.agentsEnabled}
            failedTasks={failedTasks}
          />
        </CopilotChatProvider>
      </ImmersivePluginsProvider>
    </RelayEnvironmentProvider>
  )
}

interface StandaloneInputProps {
  showHeader?: boolean
  userIsOnboarding?: boolean
  displayName?: string
  shouldClearTextOnSubmit?: boolean
  hasCEorCBAccess?: boolean
  handleUserSubmit: (
    content: string,
    selectedRepo: AgentDropdownRepository | null,
    selectedBranch: string,
    selectedAgent: SelectedAgent,
  ) => Promise<void>
  agentsEnabled?: boolean
  failedTasks: CreateTaskMutationParams[]
}

const HIDDEN_UNTIL_RESET_KEY = 'copilot-dashboard-input-hidden-until-reset'

function StandaloneInput({
  showHeader = false,
  userIsOnboarding = false,
  displayName,
  shouldClearTextOnSubmit = true,
  hasCEorCBAccess,
  handleUserSubmit,
  agentsEnabled,
  failedTasks,
}: StandaloneInputProps) {
  const chatInputRef = useRef<ChatInputRef>(null)
  const textAreaRef = useRef<HTMLTextAreaElement>(null)
  const containerRef = useRef<HTMLFormElement>(null)
  const [chatCommand, setChatCommand] = useState<CopilotChatCommandType | null>(null)
  const [sendError, setSendError] = useState(false)
  const getChatState = useGetChatState()
  const {chatQuotaExceeded, isLicensedLimited, licenseType} = useEntitlement()
  const useTaskInput = isFeatureEnabled('copilot_default_to_task_input') && agentsEnabled
  const manager = useChatManager()

  // Helper function to safely access localStorage
  const getHiddenUntilResetState = () => {
    try {
      return localStorage.getItem(HIDDEN_UNTIL_RESET_KEY) === 'true'
    } catch {
      return false
    }
  }

  // The input is disabled only when users have a limited license AND have exceeded their quota
  const isInputDisabled = isLicensedLimited && chatQuotaExceeded

  // Track the user's preference to hide the input
  const [wantsToHide, setWantsToHide] = useState(() => getHiddenUntilResetState())

  // Compute whether input should actually be hidden:
  // Only hide if user wants to hide AND input is currently disabled
  // This automatically unhides when quota is restored without needing state updates in effects
  const isHiddenUntilReset = isInputDisabled && wantsToHide

  // Clean up localStorage when quota is restored (external system sync only, no state updates)
  useEffect(() => {
    if (!isInputDisabled && wantsToHide) {
      try {
        localStorage.removeItem(HIDDEN_UNTIL_RESET_KEY)
      } catch {
        // Ignore localStorage errors
      }
    }
  }, [isInputDisabled, wantsToHide])

  const handleHideUntilReset = useCallback(() => {
    try {
      localStorage.setItem(HIDDEN_UNTIL_RESET_KEY, 'true')
    } catch {
      // Ignore localStorage errors in environments where it's unavailable
    }
    setWantsToHide(true)
    sendEvent('dotcom_chat.activate', {
      target: 'DASHBOARD_QUOTA_EXCEEDED_HIDE',
      mode: 'immersive',
    })
  }, [])

  const handleSubmit = useCallback(
    async (message: string) => {
      const state = getChatState()
      sendEvent('dotcom_chat.activate', {
        target: 'DASHBOARD_ENTRYPOINT_SEND',
        mode: 'immersive',
        richInput: true,
      })
      const success = await sendMessage(manager, message, state.currentReferences, state.model)
      setSendError(!success)
    },
    [getChatState, manager],
  )

  return (
    <div className={styles.inputContainer}>
      {showHeader && displayName && (
        <div data-testid="copilot-chat-input-header" className={styles.header}>
          <CopilotChatInputHeader
            displayName={displayName}
            showZeroUserHeader={userIsOnboarding}
            alternateZeroUserHeaderEnabled={isFeatureEnabled('zero_user_dashboard_alternate_layout')}
            feedbackDialogEnabled={isFeatureEnabled('dashboard_universe_2025_feedback_dialog')}
            feedbackSubject="dashboard_universe_2025_feedback"
            hideLogo={isHiddenUntilReset}
          />
        </div>
      )}
      {/* Hide input section and starters if user clicked X to hide until reset */}
      {!(isHiddenUntilReset && isInputDisabled) && (
        <>
          <div className={styles.inputSection}>
            {isInputDisabled && (
              <div className={styles.closeButtonContainer}>
                <Tooltip text="Hide until limits reset" direction="w">
                  <IconButton
                    icon={XIcon}
                    aria-label="Hide until limits reset"
                    size="small"
                    variant="invisible"
                    onClick={handleHideUntilReset}
                  />
                </Tooltip>
              </div>
            )}
            {sendError && (
              <Banner onDismiss={() => setSendError(false)} title="Error sending message" variant="critical">
                There was an error sending your message. Please try again.
              </Banner>
            )}
            {failedTasks.length > 0 && (
              <Banner onDismiss={() => setSendError(false)} title="Error creating task" variant="critical">
                There was an error creating your task. Please try again.
              </Banner>
            )}
            {useTaskInput ? (
              <NewTaskChatInput handleUserSubmit={handleUserSubmit} className={styles.input} />
            ) : (
              <ChatInput
                className={styles.input}
                disableAutoFocus
                disabled={isInputDisabled}
                modes={[
                  {
                    name: ModeSupportName.Ask,
                    supportsMCP: false,
                    supportsAttachments: true,
                    supportsModelSwitching: licenseType !== CopilotLicenseType.Unlicensed,
                    supportsSpaces: true,
                    supportsAutocompletion: true,
                    icon: CommentIcon,
                    placeholder: 'Ask anything',
                  },
                ]}
                // Required to show the model picker, though we won't need to start new threads
                // since this is always a new conversation.
                onNewThreadSelected={async () => {}}
                onSubmit={handleSubmit}
                chatInputRef={chatInputRef}
                textAreaRef={textAreaRef}
                containerRef={containerRef}
                onChatCommandChange={setChatCommand}
                isNewConversation
                shouldClearTextOnSubmit={!!(!hasCEorCBAccess || shouldClearTextOnSubmit)}
                disableSavedUserMessage
                slashCommandsEnabled
              />
            )}
            {isInputDisabled && <FreeChatExceededBanner />}
          </div>
          {!isInputDisabled &&
            !useTaskInput &&
            (copilotFeatureFlags.chatInputCommands && !copilotFeatureFlags.askModeDropdown ? (
              <CommandStartersAndSuggestions
                chatCommand={chatCommand}
                chatInputRef={chatInputRef}
                textAreaRef={textAreaRef}
                containerRef={containerRef}
              />
            ) : null)}
        </>
      )}
    </div>
  )
}

async function sendMessage(
  manager: CopilotChatManager,
  message: string,
  references?: CopilotChatReference[],
  model?: CopilotChatModel,
): Promise<boolean> {
  const cssClass = 'appMain--fadeOut'
  document.querySelector('.application-main')?.classList.add(cssClass)

  let success = false

  try {
    const result = await manager.sendChatMessage({
      thread: null,
      content: message,
      references: references ?? [],
      model,
      // create the thread and upload images but do not send the message yet
      noSend: true,
    })
    if (!result) return false
    const {thread, references: filteredReferences, mediaContent} = result
    const targetUrl = `/copilot/c/${thread.id}`
    copilotLocalStorage.setEntrypointMessage({
      message,
      references: filteredReferences,
      model,
      mediaContent,
      threadID: thread.id,
    })

    success = true
    setTimeout(() => {
      window.location.href = targetUrl
    }, 200)
  } finally {
    if (!success) {
      document.querySelector('.application-main')?.classList.remove(cssClass)
    }
  }
  return success
}

